CREATE TABLE compensation_plan_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL, version_number integer NOT NULL CHECK (version_number > 0), pay_type text NOT NULL CHECK (pay_type IN ('hourly', 'salary')), hourly_rate_minor bigint CHECK (hourly_rate_minor >= 0), annual_salary_minor bigint CHECK (annual_salary_minor >= 0), commission_rate_basis_points integer NOT NULL DEFAULT 1000 CHECK (commission_rate_basis_points >= 0), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((pay_type='hourly' AND hourly_rate_minor IS NOT NULL AND annual_salary_minor IS NULL) OR (pay_type='salary' AND annual_salary_minor IS NOT NULL AND hourly_rate_minor IS NULL)), UNIQUE(key, version_number));
CREATE TABLE employee_compensation_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_profile_id uuid NOT NULL REFERENCES employee_profiles(id), compensation_plan_version_id uuid NOT NULL REFERENCES compensation_plan_versions(id), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_to IS NULL OR effective_to > effective_from));
CREATE TABLE commission_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_profile_id uuid NOT NULL REFERENCES employee_profiles(id), source_quote_id uuid REFERENCES quotes(id), compensation_plan_version_id uuid NOT NULL REFERENCES compensation_plan_versions(id), attribution_basis_points integer NOT NULL CHECK (attribution_basis_points > 0 AND attribution_basis_points <= 10000), eligible_revenue_minor bigint NOT NULL CHECK (eligible_revenue_minor >= 0), commission_rate_basis_points integer NOT NULL CHECK (commission_rate_basis_points >= 0), amount_minor bigint NOT NULL CHECK (amount_minor >= 0), status text NOT NULL CHECK (status IN ('pending','earned','approved','sent_to_payroll','paid','disputed','adjusted','reversed','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX employee_compensation_assignments_active_idx ON employee_compensation_assignments (employee_profile_id, effective_from DESC) WHERE effective_to IS NULL;
CREATE INDEX commission_entries_employee_status_idx ON commission_entries (employee_profile_id, status);
